#include "sense_notify_private.h"
#include "cmd.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

#if DBG_SENSE == 1

static UInt8 speed_last_value ;

#endif

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void sense_notify_speed(UInt8 value)
{
  static Boolean state = FALSE ;

  speed.byte = value ;
  
  if (!!speed.byte != state)
    {
	  state = !!speed.byte ;
      cmd_q_insert(state ? INPUT_SPEED_SET : INPUT_SPEED_CLR, COMMAND_INSERT_TIMEOUT);
    }  
       
  speed.bit.is_detected |= !!speed.byte ;

  #if DBG_SENSE == 1
    {
      if(value != speed_last_value)
        {
          speed_last_value = value ;

          sense_notify_dbg_print(value == 0? "Speed Off" : "\r\nSpeed Upd " , &value , 1);
        }
    } 
  #endif


}

